CREATE TABLE hq_jobs (repository TEXT NOT NULL, goal TEXT NOT NULL, job_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','VERIFYING','BLOCKED','AWAITING_APPROVAL')), revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991), epoch INTEGER NOT NULL CHECK(epoch BETWEEN 1 AND 9007199254740991), holder TEXT, expires_ms INTEGER NOT NULL CHECK(expires_ms>=0), mutation_ms INTEGER NOT NULL, last_operation TEXT NOT NULL, PRIMARY KEY(repository,goal,job_id));
CREATE TABLE hq_events (repository TEXT NOT NULL, goal TEXT NOT NULL, job_id TEXT NOT NULL, revision INTEGER NOT NULL, operation TEXT NOT NULL, state TEXT NOT NULL, epoch INTEGER NOT NULL, mutation_ms INTEGER NOT NULL, evidence_digest TEXT, PRIMARY KEY(repository,goal,job_id,revision), FOREIGN KEY(repository,goal,job_id) REFERENCES hq_jobs(repository,goal,job_id));
CREATE TABLE hq_receipts (repository TEXT NOT NULL, goal TEXT NOT NULL, job_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, principal TEXT NOT NULL, request_digest TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(repository,goal,job_id,idempotency_key), FOREIGN KEY(repository,goal,job_id) REFERENCES hq_jobs(repository,goal,job_id));
